<div class="card card-body mb-4 table-responsive"><h4>Fee / product / service catalog</h4><table class="table"><thead><tr><th>Code</th><th>Name</th><th>Kind</th><th>Default rate</th><th>Frequency</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($items as $r): ?><tr><td><?= sanitize($r['code']) ?></td><td><?= sanitize($r['name']) ?></td><td><?= sanitize($r['kind']) ?></td><td><?= acMoney((int)$r['rate_minor']) ?></td><td><?= sanitize($r['frequency']) ?></td><td><?= $r['is_active']?'Active':'Inactive' ?></td><td><?php if($ac->can('catalog')): ?><a href="<?= acUrl('fees',['edit'=>$r['id']]) ?>">Edit</a><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="7">Add your school's fee items to begin.</td></tr><?php endif; ?></tbody></table></div>
